using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;

var tcpEndpoint = new IPEndPoint(IPAddress.Loopback, 9000);
var udpEndpoint = new IPEndPoint(IPAddress.Loopback, 9001);
byte[] payload = Encoding.UTF8.GetBytes("seq=105;value=72\n");
byte[] buffer = new byte[2048];

using (var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(2)))
using (var tcp = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp))
{
    await tcp.ConnectAsync(tcpEndpoint, deadline.Token);

    int offset = 0;
    while (offset < payload.Length)
    {
        int sent = await tcp.SendAsync(payload.AsMemory(offset), SocketFlags.None, deadline.Token);
        if (sent == 0) throw new IOException("TCP send made no progress");
        offset += sent;
    }

    int received = await tcp.ReceiveAsync(buffer, SocketFlags.None, deadline.Token);
    if (received == 0)
    {
        // 非零長度buffer下，對端已正常結束這個傳送方向。
        // 若協定預期的回覆尚未完整，這次回覆仍不完整。
    }
    else
    {
        // 只處理buffer[0..received]；交給協定解析器累積或判斷回覆。
    }
}

using (var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(2)))
using (var udp = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp))
{
    int sent = await udp.SendToAsync(payload.AsMemory(), SocketFlags.None, udpEndpoint, deadline.Token);
    if (sent != payload.Length) throw new IOException("Unexpected UDP datagram send length");

    EndPoint peer = new IPEndPoint(IPAddress.Any, 0);
    var reply = await udp.ReceiveFromAsync(buffer, SocketFlags.None, peer, deadline.Token);
    // 檢查reply.RemoteEndPoint、訊息識別碼與期限，再交給應用處理。
    // reply.ReceivedBytes == 0可代表合法的空datagram，不是TCP式EOF。
}
